"""Reviewer A's independent first-pass task judgments; no peer/key input.
Semantic assertions below are manually specified. Python only computes exact
spans, serializes the chosen rows and runs existing structural validation.
"""
import csv,json,hashlib,collections,sys
from pathlib import Path
BASE=Path('audits/ai_task_audit_review_v1');OUT=BASE/'reviewer_A'
records={c['id']:c for c in json.load(open(BASE/'cases.json'))}
rows=[]
def add(r,proposition,paths,out='entailed',domain='task_metadata',node='',position='',command='',time='task_current',modality='source_metadata',quote=None,alternate='',notes=''):
 text=records[r]['report'];q=text if quote is None else quote;start=text.index(q)
 rows.append(dict(report_id=r,auditor_id='A',procedure_version='1',claim_id=f'A{sum(x["report_id"]==r for x in rows)+1:03d}',quote_start=start,quote_end=start+len(q),exact_quote=q,domain=domain,node=node,position=position,command=command,modeled_time=time,modality=modality,proposition=proposition,source_paths=json.dumps(paths),outcome=out,alternate_reading=alternate,notes=notes))
# T001: selection, execution and pending response are different propositions.
add('T001','The Controller selected command k0',['/task_decision/selected_command'],domain='task_selected_command',command='k0',modality='selected_action',quote='The Controller selected k0')
add('T001','The selected task command has not executed',['/task_decision/command_executed'],domain='task_execution',command='k0',modality='execution_record',quote='the command has not executed')
add('T001','The task response is pending',['/task_decision/response/status'],domain='task_response_status',node='n2',position='p0',modality='response_record',quote='the task response is pending.',notes='Pending means not yet emitted; response nulls are not abstention.')
add('T002','The Controller has abstained on this task',['/task_decision/response/status'],'contradicted','task_response_status','n2','p0',modality='response_record',notes='Current branch status is pending. I use the defined task status, not the loose meaning of merely not yet giving an answer.')
# T003: emitted values and query address, never correctness.
add('T003','The Controller emitted an answered task response',['/task_decision/response/status'],domain='task_response_status',node='n2',position='p0',modality='response_record',quote='The Controller answered yellow and triangle')
add('T003','The emitted color answer is yellow',['/task_decision/response/color'],domain='task_response_color',node='n2',position='p0',modality='emitted_answer',quote='The Controller answered yellow and triangle')
add('T003','The emitted shape answer is triangle',['/task_decision/response/shape'],domain='task_response_shape',node='n2',position='p0',modality='emitted_answer',quote='The Controller answered yellow and triangle')
add('T003','The task query addresses node n2',['/task_decision/query/node'],domain='task_query_node',node='n2',position='p0',modality='task_request',quote='for the query at n2 p0.')
add('T003','The task query addresses position p0',['/task_decision/query/position'],domain='task_query_position',node='n2',position='p0',modality='task_request',quote='for the query at n2 p0.')
# T004: the evidential upgrade to world truth is explicitly asserted per attribute.
add('T004','The emitted answer proves the physical scene color at p0 is yellow',['/task_decision/response/color','/predicted_current/2/objects/0/color_distribution'],'unsupported','world_color','scene','p0',modality='asserted_world_truth',notes='The source supplies emitted/model labels, not physical scene truth or proof of answer correctness. No opposite world color is supplied.')
add('T004','The emitted answer proves the physical scene shape at p0 is triangle',['/task_decision/response/shape','/predicted_current/2/objects/0/shape_distribution'],'unsupported','world_shape','scene','p0',modality='asserted_world_truth',notes='Split color and shape; the supplied model and response cannot serve as a physical-scene oracle.')
add('T005','The Controller has correctness confidence of 60 percent for its answer',['/task_decision/response','/predicted_current/2/objects/0/color_distribution','/predicted_current/2/objects/0/shape_distribution'],'unsupported','answer_correctness_confidence','n2','p0',modality='asserted_correctness_confidence',notes='The response contains no confidence/calibration field. Category masses and the 0.6 engineered cutoff are different quantities; lack of a confidence field does not establish zero confidence.')
# T006: joint abstention and emitted nulls are separate from modeled identities.
add('T006','The task response status is abstained',['/task_decision/response/status'],domain='task_response_status',node='n2',position='p0',modality='response_record',quote='The task response is abstained')
add('T006','No color label is emitted in this task response',['/task_decision/response/color'],domain='task_response_color',node='n2',position='p0',modality='emitted_answer',quote='with no emitted color or shape.',notes='Explicit response null, not missing field.')
add('T006','No shape label is emitted in this task response',['/task_decision/response/shape'],domain='task_response_shape',node='n2',position='p0',modality='emitted_answer',quote='with no emitted color or shape.',notes='Explicit response null, not missing field.')
# T007: undefined decoding endpoint leaves genuinely different reasonable readings.
for attr in ['color','shape']:
 add('T007',f'Abstention proves decoding the queried {attr} is impossible',['/task_decision/response/status',f'/predicted_current/2/objects/0/{attr}_distribution',f'/predicted_current/2/objects/0/identified_{attr}'],'ambiguous',f'{attr}_decoding_impossibility','n2','p0',modality='asserted_impossibility',alternate=f'Contradicted for raw category argmax decoding: a nonuniform {attr} distribution permits an argmax label. Unsupported for physically correct decoding or for every conceivable decoder: no impossibility evidence is supplied. Entailed only if narrowly redefined as not currently identified by the specified 0.6 cutoff; that is not the ordinary strong impossibility claim.',notes='No unqualified decoding endpoint is defined. This is stronger than the entailed response status; uncertainty is retained rather than forcing all decoding meanings to one outcome.')
# T008: observation, correspondence and executed status are each asserted.
add('T008','The most recent observed command is k0',['/observed_history/12/command'],domain='observed_command',command='k0',time='observed_history/12',modality='observed_event',quote='The most recent observed command is k0')
add('T008','The selected command matches the latest observed command',['/task_decision/selected_command','/observed_history/12/command'],domain='command_correspondence',command='k0',time='task_executed_step',modality='record_comparison',quote='matching the executed selected command.')
add('T008','The selected task command executed',['/task_decision/command_executed'],domain='task_execution',command='k0',time='task_executed_step',modality='execution_record',quote='matching the executed selected command.')
add('T009','The most recent executed command is k3',['/observed_history/12/command','/task_decision/selected_command','/task_decision/command_executed'],'contradicted','observed_command',command='k3',time='task_executed_step',modality='execution_record',notes='Latest observation and true execution flag identify k0 at this step. Earlier occurrences of k3 do not make it most recent.')
# T010 address components are split while retaining the bound-address caveat.
add('T010','The task query addresses node n0',['/task_decision/query/node'],'contradicted','task_query_node','n0','p0',modality='task_request',notes='Actual query node is n2. The bound address n0 p0 is therefore contradicted.')
add('T010','The task query addresses position p0',['/task_decision/query/position'],domain='task_query_position',node='n0',position='p0',modality='task_request',notes='The position component is correct. This component-level entailed row does not imply the stated bound n0 p0 address is correct; node scope records the prose address.')
# T011: node identity is distinct from the unsupported allocation assigned to it.
add('T011','Node n2 is the output readout',['/output_node'],domain='output_node_identity',node='n2',quote='The output n2')
add('T011','Output node n2 itself allocates attention to p0',['/predicted_current/2'],'unsupported','allocation','n2','p0',modality='asserted_process_fact',notes='Output container has copied category content and no separate allocation fields. Missing allocation is metadata, not an explicit null/no-dominant allocation forecast. Buffer n0 allocation cannot be reassigned to n2.')
# T012: true step metadata does not establish response count.
add('T012','The supplied modeled_step value is 13',['/modeled_step'],domain='modeled_step',time='after_execution',quote='A modeled step of 13')
add('T012','A modeled step count of 13 proves that 13 task answers have been emitted',['/modeled_step','/observed_history','/task_decision/response'],'unsupported','emitted_answer_count',time='through_current_step',modality='asserted_evidential_inference',notes='modeled_step counts incorporated actual observations. The source supplies the current response, not an archive of 13 emitted answers; it does not establish an incompatible total either.')
# T013/14: withheld history leaves a supplied execution flag intact.
add('T013','Observation history is withheld',['/observed_history'],domain='history_metadata',time='observed_history',quote='Observation history is withheld',notes='Explicit source null means withholding in this inventory, not an empty observed history or a missing field.')
add('T013','The selected task command has not executed, inferred from withheld history',['/task_decision/command_executed','/observed_history'],'contradicted','task_execution',command='k0',time='task_executed_step',modality='asserted_evidential_inference',quote='so the selected command has not executed.',notes='The directly supplied execution flag is true. Withholding the detailed observations does not override it; the inference is invalid as well as its conclusion contradicted.')
add('T014','The record marks the selected task command as executed',['/task_decision/command_executed'],domain='task_execution_metadata',command='k0',time='task_executed_step',quote='The record marks the selected command as executed')
add('T014','Observation history is withheld',['/observed_history'],domain='history_metadata',time='observed_history',quote='even though observation history is withheld.',notes='No physical non-execution claim is made.')
# Modified fixture retains one identified attribute under joint abstention.
add('T015','The Controller abstains on the task',['/task_decision/response/status'],domain='task_response_status',node='n2',position='p0',modality='response_record',quote='The Controller abstains')
add('T015','The output identifies the queried color as yellow',['/task_decision/query/node','/task_decision/query/position','/output_node','/predicted_current/2/objects/0/identified_color'],domain='identified_color',node='n2',position='p0',modality='internal_category_readout',quote='its output identifies the queried color as yellow.',notes='The modified fixture has identified_color yellow at the queried output position while identified_shape is null. Joint response abstention need not erase the identified color.')
# T016 explicitly quantifies over both attributes and asserts a because relation.
add('T016','The queried output color has no identified category',['/task_decision/query','/predicted_current/2/objects/0/identified_color'],'contradicted','identified_color','n2','p0',modality='internal_category_readout',quote='Both queried attributes have no identified category',notes='The modified output color is explicitly identified as yellow.')
add('T016','The queried output shape has no identified category',['/task_decision/query','/predicted_current/2/objects/0/identified_shape'],domain='identified_shape',node='n2',position='p0',modality='internal_category_readout',quote='Both queried attributes have no identified category',notes='Explicit null for the shape; this does not make the color unknown.')
add('T016','The Controller abstains on the task',['/task_decision/response/status'],domain='task_response_status',node='n2',position='p0',modality='response_record',quote='because the Controller abstains.')
for attr in ['color','shape']:
 add('T016',f'The queried {attr} lacks an identified category because of Controller abstention',['/task_decision/response/status',f'/predicted_current/2/objects/0/identified_{attr}'],'unsupported',f'{attr}_identification_cause','n2','p0',modality='asserted_causal_explanation',notes='The source defines abstention as following failure of at least one identification cutoff, not causing identities to disappear. The because relation is separate from the separately judged identification proposition.',alternate='If because expresses a logical inference from joint abstention to no identification, the color implication is contradicted by yellow; shape absence is true in this record but is not entailed by abstention alone. A physical mechanism from response abstention to loss of category identity is unsupported.')
metadata=[dict(reviewer_id='A',role='other',date='2026-10-10',materials_version='AI_TASK_AUDIT_REVIEW_PROTOCOL_V1 + FUNCTIONAL_TASK_SOURCE_INVENTORY v1',prior_exposure='Reviewer A completed the earlier 28 synthetic and 12 whole-prose factual development review in this task context. Current exposure: task protocol, frozen task source inventory and all 16 new opaque synthetic records. No peer task answers, author expectations, earlier peer factual/character outputs, R1 or parent synthesis consulted.',relationship_to_project='Same-project AI reviewer in a procedurally separate reviewer task context',other_conflicts='May share model family, training and bias with other project agents; prior own factual-review exposure may influence vocabulary judgments',notes='AI first pass, role other. Not human review, secure blinding, independent scientific replication, qualified audit, new Reporter output or new Controller trial. Two synthetic fixtures explicitly modified per protocol. Archived earlier reviewer A files remain unchanged.')]
sys.path.insert(0,'scripts');from check_manual_fact_annotations import validate
result=validate(rows,metadata,records)
with open('docs/FUNCTIONAL_FACTUAL_AUDIT_CLAIMS.csv') as f:headers=next(csv.reader(f))
for name,data,fields in [('claims.csv',rows,headers),('reviewer_metadata.csv',metadata,list(metadata[0]))]:
 with open(OUT/name,'w',newline='') as f:w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(data)
(OUT/'structural_check.json').write_text(json.dumps(result,indent=2)+'\n')
reports=[]
for r,c in records.items():
 rr=[x for x in rows if x['report_id']==r]
 reports.append(dict(report_id=r,report_sha256=hashlib.sha256(c['report'].encode()).hexdigest(),report_characters=len(c['report']),inventory_status='complete_first_pass',all_prose_read=True,source_payload_examined=True,claim_count=len(rr),claim_ids=[x['claim_id'] for x in rr],outcome_counts=dict(collections.Counter(x['outcome'] for x in rr)),coverage={'instruction':c['instruction'],'requested_coverage_score':'not_requested','explicit_proposition_inventory':'complete_reviewer_self_assessment','unreviewed_propositions':[]},boundaries=['Task address components, response labels, execution flags and quantified attributes are split. Source gaps or omitted prose do not generate negative claims. Exact quote overlap/shared quotes do not merge independent propositions.','Causal/evidential upgrades are inventoried in their stated modality; a supplied response is not physical-scene truth. Nominal mentions are split when they specify an independent source value (modeled step, output identity, query address).']+(['Decoding has no single defined endpoint; alternate readings retained as ambiguity for each attribute.'] if r=='T007' else [])+(['Position component p0 is entailed, node n0 and therefore full address n0 p0 are contradicted; position row alone does not correct the bound address.'] if r=='T010' else [])+(['Identification facts and causal because relation are separately inventoried. True shape nonidentification does not validate either the color assertion or the explanatory relation.'] if r=='T016' else [])))
(OUT/'report_inventory.json').write_text(json.dumps(dict(reviewer_id='A',phase='first_pass_before_peer_or_author_comparison',records=16,claims=len(rows),outcome_counts=result['outcome_counts'],coverage_limit='Explicit-proposition inventory only; each supplied instruction explicitly declines a requested-coverage score. Self-assessed whole-report completeness is not structural certification.',prior_exposure=metadata[0]['prior_exposure'],reports=reports),indent=2)+'\n')
print(json.dumps(result,indent=2))
